<?php require 'config.php'; $page_title='Admin — HOSTNEIL';$err=''; if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){csrf_check();$email=trim($_POST['email']??'');$pass=(string)($_POST['password']??'');if(hash_equals(ADMIN_EMAIL,$email)&&hash_equals(ADMIN_PASSWORD,$pass)){session_regenerate_id(true);$_SESSION['is_admin']=true;redirect('admin.php');}else $err='Invalid admin credentials.';} if(is_admin()){ $d=store_read(); if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='order_status'){foreach($d['orders'] as &$o)if((int)$o['id']===$id)$o['status']=$_POST['status']??'pending';unset($o);store_write($d);flash('Order status updated.');redirect('admin.php#orders');}if($action==='payment_status'){foreach($d['payments'] as &$p)if((int)$p['id']===$id){$p['status']=$_POST['status']??'pending';if($p['status']==='verified'){foreach($d['orders'] as &$o)if((int)$o['id']===(int)$p['order_id'])$o['status']='paid';unset($o);}}unset($p);store_write($d);flash('Payment status updated.');redirect('admin.php#payments');}if($action==='quote_status'){foreach($d['vps_quotes'] as &$q)if((int)$q['id']===$id)$q['status']=$_POST['status']??'pending';unset($q);store_write($d);flash('Quote status updated.');redirect('admin.php#quotes');}if($action==='post_add'){ $title=trim($_POST['title']??'');$slug=preg_replace('/[^a-z0-9-]/','-',strtolower(trim($_POST['slug']??'')));if($title&&$slug){$d['posts'][]=['id'=>count($d['posts'])?max(array_column($d['posts'],'id'))+1:1,'title'=>$title,'title_bn'=>trim($_POST['title_bn']??$title),'slug'=>$slug,'excerpt'=>trim($_POST['excerpt']??''),'excerpt_bn'=>trim($_POST['excerpt_bn']??''),'body'=>trim($_POST['body']??''),'body_bn'=>trim($_POST['body_bn']??''),'published'=>isset($_POST['published']),'created'=>date('Y-m-d')];store_write($d);flash('Blog post added.');redirect('admin.php#blog');}} $d=store_read(); } }
